action.command:
python3 << 'EOF'
import paramiko
c = paramiko.SSHClient()
c.set_missing_host_key_policy(paramiko.AutoAddPolicy())
c.connect('46.202.154.25', 22, 'root', '2N00py123+++')

# Update nginx to add no-cache headers for HTML/JS
new_config = """server {
    listen 80;
    listen [::]:80;
    server_name arelorian.de www.arelorian.de;
    location /.well-known/acme-challenge/ { root /var/www/html; }
    location / { return 301 https://$host$request_uri; }
}

server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name arelorian.de www.arelorian.de;
    ssl_certificate /etc/letsencrypt/live/arelorian.de/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/arelorian.de/privkey.pem;
    root /opt/areloria/client/dist;
    index index.html;
    gzip on;
    gzip_types text/plain text/css application/javascript application/json image/svg+xml;

    # No cache for dynamic content
    location / {
        try_files $uri /index.html;
        add_header Cache-Control "no-cache, no-store, must-revalidate";
    }

    location /index.html {
        add_header Cache-Control "no-cache, no-store, must-revalidate";
    }

    location /assets/ {
        expires -1;
        add_header Cache-Control "no-cache, no-store, must-revalidate";
    }

    location /ws {
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_read_timeout 86400;
    }

    location /client-config.json {
        proxy_pass http://127.0.0.1:3000;
        proxy_set_header Host $host;
    }

    location /world {
        proxy_pass http://127.0.0.1:3000;
        proxy_set_header Host $host;
    }

    location /api {
        proxy_pass http://127.0.0.1:3000;
        proxy_set_header Host $host;
    }
}
"""

sftp = c.open_sftp()
with sftp.file('/etc/nginx/sites-enabled/arelorian.de', 'w') as f:
    f.write(new_config)

c.exec_command("nginx -t && nginx -s reload")
print("Cache headers added!")

c.close()
EOF

